import{_ as a,o as n,c as s,a3 as r,j as t}from"./chunks/framework.Cc-oPviL.js";const _=JSON.parse('{"title":"第九章　预测评价","description":"","frontmatter":{},"headers":[],"relativePath":"timeseries/09.md","filePath":"timeseries/09.md"}'),e={name:"timeseries/09.md"};function d(l,o,i,p,u,g){return n(),s("div",null,[...o[0]||(o[0]=[r('<h1 id="第九章-预测评价" tabindex="-1">第九章　预测评价 <a class="header-anchor" href="#第九章-预测评价" aria-label="Permalink to &quot;第九章　预测评价&quot;">​</a></h1><p>预测做出来之后，怎么评价它同样有讲究。本章讲 RMSE、MAE、MAPE 的性质差异，基准的选择，DM 检验，以及六种信息泄漏形态。</p><h2 id="_9-1-常用指标" tabindex="-1">9.1 常用指标 <a class="header-anchor" href="#_9-1-常用指标" aria-label="Permalink to &quot;9.1 常用指标&quot;">​</a></h2><p>设预测误差 eₜ = yₜ − ŷₜ，样本量 n。</p><blockquote><p><strong>RMSE</strong> = √( (1/n) Σ eₜ² )<br><strong>MAE</strong> = (1/n) Σ |eₜ|<br><strong>MAPE</strong> = (100/n) Σ |eₜ / yₜ|<br><strong>MASE</strong> = MAE / [ (1/(n−m)) Σₜ |yₜ − yₜ₋m| ]<br><strong>sMAPE</strong> = (100/n) Σ 2|eₜ| / (|yₜ| + |ŷₜ|)</p></blockquote><p>其中 MASE 的分母是&quot;朴素预测&quot;（seasonal naive，m 为季节周期；非季节时 m = 1）的平均绝对误差，起缩放作用。</p><h2 id="_9-2-各指标的性质与适用" tabindex="-1">9.2 各指标的性质与适用 <a class="header-anchor" href="#_9-2-各指标的性质与适用" aria-label="Permalink to &quot;9.2 各指标的性质与适用&quot;">​</a></h2><table tabindex="0"><thead><tr><th>指标</th><th>量纲</th><th>对大误差</th><th>对异常值</th><th>可跨序列比较</th><th>主要问题</th></tr></thead><tbody><tr><td>RMSE</td><td>同原序列</td><td>惩罚重（平方）</td><td>敏感</td><td>否</td><td>被少数大误差主导</td></tr><tr><td>MAE</td><td>同原序列</td><td>线性</td><td>稳健</td><td>否</td><td>不区分误差来源</td></tr><tr><td>MAPE</td><td>无量纲（%）</td><td>线性</td><td>敏感（y 小时爆炸）</td><td>有限</td><td>y 接近 0 时无意义；高估低估不对称</td></tr><tr><td>MASE</td><td>无量纲</td><td>线性</td><td>稳健</td><td>是</td><td>需要基准序列</td></tr><tr><td>sMAPE</td><td>无量纲（%）</td><td>线性</td><td>较稳健</td><td>有限</td><td>仍有零点问题；上下界不对称</td></tr></tbody></table><p>★ <strong>RMSE 与 MAE 的关系</strong>：恒有 RMSE ≥ MAE，等号仅在所有误差绝对值相等时成立。两者差距越大，说明误差分布越不均匀（存在少数大误差）。因此<strong>同时报告 RMSE 与 MAE 是有信息量的</strong>——它们的比值反映了误差的集中程度。</p><h2 id="_9-3-mape-的陷阱" tabindex="-1">9.3 MAPE 的陷阱 <a class="header-anchor" href="#_9-3-mape-的陷阱" aria-label="Permalink to &quot;9.3 MAPE 的陷阱&quot;">​</a></h2><p>MAPE 是最常被误用的指标，有三个必须知道的问题：</p><p><strong>（1）y 接近 0 时爆炸。</strong> 若真实值为 0.5 而预测为 1.5，误差 1 的 MAPE 是 200%。若真实值为 0，MAPE 无定义。<strong>价格、价差、收益率、需求量在低谷期都可能接近 0。</strong></p><p><strong>（2）对高估与低估不对称。</strong> 预测值大于真实值时，分母是较小的真实值，误差被放大；预测值小于真实值时，分母较大，误差被缩小。因此 MAPE 系统性地<strong>惩罚高估多于低估</strong>。</p><p><strong>（3）不可加总。</strong> 不同时期的 MAPE 不能简单平均得到&quot;总 MAPE&quot;，因为各期分母不同。</p><p><strong>替代方案</strong>：MASE（有基准缩放、无零点问题）、sMAPE（部分缓解）、或者直接报告 MAE 并说明量纲。</p><h2 id="_9-4-为什么必须有基准" tabindex="-1">9.4 为什么必须有基准 <a class="header-anchor" href="#_9-4-为什么必须有基准" aria-label="Permalink to &quot;9.4 为什么必须有基准&quot;">​</a></h2><p>任何预测模型都必须与<strong>朴素基准</strong>比较，否则无法判断&quot;模型是否真的学到了东西&quot;。</p>',17),t("table",{tabindex:"0"},[t("thead",null,[t("tr",null,[t("th",null,"基准"),t("th",null,"公式"),t("th",null,"适用")])]),t("tbody",null,[t("tr",null,[t("td",null,"Naive（随机游走）"),t("td",null,"ŷ_{T+h} = y_T"),t("td",null,"价格、股价等强持续性序列")]),t("tr",null,[t("td",null,"Seasonal naive"),t("td",{"T+h−m":""},"ŷ_{T+h} = y_"),t("td",null,"有明显季节性的序列")]),t("tr",null,[t("td",null,"Drift（带漂移）"),t("td",null,"ŷ_{T+h} = y_T + h·(y_T − y₁)/(T−1)"),t("td",null,"有长期趋势的序列")]),t("tr",null,[t("td",null,"Mean"),t("td",null,"ŷ_{T+h} = ȳ"),t("td",null,"无明显趋势与季节的序列")])])],-1),r('<p>★ <strong>复杂模型输给基准是常态，不是异常。</strong> 在 M 系列预测竞赛中，绝大多数复杂方法都没能显著超过简单基准的组合。因此&quot;我的模型 RMSE 是 3.5&quot;本身没有意义，必须说&quot;基准是 3.6，改善 2.8%&quot;。</p><p>★ <strong>基准的选择会影响结论的方向。</strong> 若序列有强趋势，Drift 会比 Naive 强很多；若序列是纯随机游走，Naive 就是理论最优。选一个弱基准会让模型显得很好，这是不诚实的做法。合理的选择是：<strong>报告多个基准，并说明哪个最贴近数据的性质</strong>。</p><h2 id="_9-5-diebold-mariano-检验" tabindex="-1">9.5 Diebold-Mariano 检验 <a class="header-anchor" href="#_9-5-diebold-mariano-检验" aria-label="Permalink to &quot;9.5 Diebold-Mariano 检验&quot;">​</a></h2><p>用来判断两个模型的预测精度差异是否统计显著。</p><p>设损失函数为 L（如平方误差或绝对误差），定义损失差</p><blockquote><p>dₜ = L(e₁ₜ) − L(e₂ₜ)</p></blockquote><p>原假设 H₀: E(dₜ) = 0（两个模型精度相同）。检验统计量</p><blockquote><p><strong>DM = d̄ / √( 2π f̂_d(0) / T )</strong></p></blockquote><p>其中 f̂_d(0) 是 dₜ 的谱密度在零频处的估计（用于修正序列相关），T 是预测期数。</p><p><strong>小样本修正</strong>：Harvey-Leybourne-Newbold 修正把统计量乘以 √[(T + 1 − 2h + h(h−1)/T) / T]，并改用 t 分布，改善小样本表现。</p><p>★ <strong>T 很小时的困境</strong>：12 个预测点上，DM 检验的功效极低，即使真实差异存在也很难检出。此时有两种诚实的做法：</p><ol><li>做检验，但明确说明&quot;样本过短，检验功效不足，不拒绝不能作为&#39;无差异&#39;的证据&quot;；</li><li>不做检验，只报告点估计与改善率，并在文字上明确&quot;不主张统计显著性&quot;。</li></ol><p><strong>两种都比&quot;用文字反复强调不能宣称显著、却完全不提检验&quot;更规范</strong>，因为后者会让评阅人怀疑作者不知道有这个工具。</p><h2 id="_9-6-信息泄漏的六种形态" tabindex="-1">9.6 信息泄漏的六种形态 <a class="header-anchor" href="#_9-6-信息泄漏的六种形态" aria-label="Permalink to &quot;9.6 信息泄漏的六种形态&quot;">​</a></h2><p>这是时间序列建模中最严重的错误类型，因为它会让结果看起来很好但完全无效。</p><p><strong>（1）用全样本做标准化/缩放。</strong> 计算全样本的均值、标准差、min/max 来标准化，等于把测试期的信息带进了训练。正确做法：只用训练段计算缩放参数。</p><p><strong>（2）用测试集选模。</strong> 反复在测试集上比较不同模型、不同参数，最终选出的&quot;最优&quot;模型已经过拟合了测试集。正确做法：测试集只用一次。</p><p><strong>（3）用未来信息构造特征。</strong> 例如用中心移动平均（含未来值）、用全样本的季节因子、用未来才会公布的修订数据。</p><p><strong>（4）用全样本估计的参数做样本外预测。</strong> 用 2000–2025 全样本估出的参数去&quot;预测&quot;2025 年，等于用了 2025 年的数据估参。正确做法：预测 2025 年 1 月时，只能用截至 2024 年 12 月的数据估参。</p><p><strong>（5）重复使用测试集调参。</strong> 第一次用完测试集后改了模型，再用同一个测试集评价——此时测试集已不再是&quot;未见过&quot;的数据。</p><p><strong>（6）数据修订（vintage 问题）。</strong> 用今天下载的修订后数据回测历史，而当时决策者只能看到当时发布的初值。这在宏观数据上尤其严重（GDP、就业数据会被多次修订）。</p><p>★ <strong>检验是否泄漏的一个简单办法</strong>：把你的整个流程想象成&quot;站在预测原点当天&quot;，问自己&quot;这一刻我真的知道这个数字吗？&quot;如果答案是否定的，就有泄漏。</p><h2 id="要点" tabindex="-1">要点 <a class="header-anchor" href="#要点" aria-label="Permalink to &quot;要点&quot;">​</a></h2><ol><li>RMSE 惩罚大误差、MAE 稳健，恒有 RMSE ≥ MAE，两者比值反映误差集中度。</li><li>MAPE 在 y 接近 0 时爆炸，且系统性惩罚高估，需谨慎使用。</li><li>必须与 Naive、Drift 等基准比较；复杂模型输给基准是常态。</li><li>DM 检验判断精度差异是否显著，小样本功效低，需诚实说明。</li><li>信息泄漏有六种形态，最隐蔽的是&quot;用全样本做缩放&quot;和&quot;用修订后数据回测&quot;。</li><li>判断泄漏的黄金问题：站在预测原点当天，这个数字我知道吗？</li></ol><h2 id="自测-3-问" tabindex="-1">自测 3 问 <a class="header-anchor" href="#自测-3-问" aria-label="Permalink to &quot;自测 3 问&quot;">​</a></h2><p><strong>Q1：RMSE 和 MAE 有什么区别？两者比值说明什么？</strong></p><details class="details custom-block"><summary>点开看答案</summary><p><strong>RMSE</strong> 对大误差惩罚更重，<strong>MAE</strong> 更稳健，恒有 <strong>RMSE ≥ MAE</strong>。</p><p>两者比值反映误差的集中程度：比值越大，说明有少数特别大的误差。</p></details><p><strong>Q2：MAPE 有什么陷阱？</strong></p><details class="details custom-block"><summary>点开看答案</summary><p>① 实际值 <strong>y 接近 0 时 MAPE 会爆炸</strong>；② <strong>系统性地对高估惩罚更重</strong>，不对称。</p><p>所以序列接近 0 时不要用 MAPE。</p></details><p><strong>Q3：怎么判断建模流程里有没有信息泄漏？举两个最隐蔽的例子。</strong></p><details class="details custom-block"><summary>点开看答案</summary><p>黄金问题：<strong>站在预测原点当天，这个数字我当时知道吗？</strong> 不知道就是泄漏。</p><p>最隐蔽的两种：① <strong>用全样本计算均值/标准差/min-max 做缩放</strong>；② <strong>用今天下载的修订后数据回测历史</strong>（当时只能看到初值）。</p></details>',31)])])}const M=a(e,[["render",d]]);export{_ as __pageData,M as default};
